  'useEverywhere.modalAria': 'Usa Pixflow Design ovunque',
  'useEverywhere.modalTitle': 'Usa Pixflow Design ovunque',
  'useEverywhere.modalSubtitle': 'Integra Pixflow Design in qualsiasi IDE, agent o script — CLI, HTTP, MCP e Skill. Usa “Copia la guida per un agent” e incollala in Claude Code, Codex, Cursor, openclaw o hermes per configurare tutto.',
