  'designFiles.usefulInfoTip4': 'Scegli un design system per risultati coerenti con il brand.',
  'designFiles.usefulInfoTip5': 'Senza idee? Prova un template plugin nella Community in Home.',
  'designFiles.usefulInfoTip6': "Usa i commenti sull’anteprima per richiedere modifiche mirate senza ricominciare.",
  'designFiles.usefulInfoTip7': "Mantieni allegate le schermate e i brief originali, affinché le modifiche future rispettino l’intento iniziale.",
  'designFiles.usefulInfoTip8': "Quando il design è quasi pronto, chiedi una rifinitura invece di rigenerare l’intera pagina.",
