  "wp.message.26a6374fbf59": "Un componente aggiuntivo Pixflow non si è avviato. Verifica che i plugin Pixflow siano compatibili, poi ricarica. Altre funzionalità potrebbero restare disponibili.",
  "wp.message.ca7714cffbcc": "Attiva Pro",
  "wp.message.197c83a2f752": "Recupera gli strumenti premium con il componente aggiuntivo Pro. Licenza, contenuti e impostazioni salvate restano invariati. Se usavi l’autenticazione a due fattori di Bricks, riattivala nelle impostazioni dopo aver attivato Pro.",
